"""Class for handling all Applications related to remote XVI automation"""

from ..desktop.application_aut import Application_AUT
from interops.libraries.squish_actions.constants import XVI_APP_NAME, XVI_REGISTRATION_APP_NAME, SIMDIALOGS_APP_NAME

class XviAutController(Application_AUT):

    def __init__(self, serverAddress: str, serverPort: int = 4322) -> None:
        Application_AUT.__init__(self, serverAddress, serverPort)

    @classmethod
    def xvi_aut(cls, serverAddress: str, serverPort: int, attachPort: int = 7101):
        """Function to modify variables in the default XviAutController class to target the main XVI application,
        on a system with a squish server running.

        :param serverAddress: Host IP Address of the system you wish to target with a squish server running
        :type serverAddress: str
        :param serverPort: Network Port number the running squish server. Default value is 4322
        :type serverPort: int, optional
        :param attachPort: Network Port number designated as the squish attaching port for the AUT (startwinaut.exe)
        :type attachPort: int, optional
        """
        aut_cls = cls(serverAddress, serverPort)
        aut_cls._aut_name = XVI_APP_NAME
        aut_cls.attach_port = str(attachPort)
        return aut_cls

    @classmethod
    def xvi_registration_aut(cls, serverAddress: str, serverPort: int, attachPort: int = 7103):
        """Function to modify variables in the default XviAutController class to target the Volume View
        Registration window in the XVI application, on a system with a squish server running.

        :param serverAddress: Host IP Address of the system you wish to target with a squish server running
        :type serverAddress: str
        :param serverPort: Network Port number the running squish server. Default value is 4322
        :type serverPort: int, optional
        :param attachPort: Network Port number designated as the squish attaching port for the AUT (startwinaut.exe)
        :type attachPort: int, optional
        """
        aut_cls = cls(serverAddress, serverPort)
        aut_cls._aut_name = XVI_REGISTRATION_APP_NAME
        aut_cls.attach_port = str(attachPort)
        return aut_cls

    @classmethod
    def sim_dialogs_aut(cls, serverAddress: str, serverPort: int, attachPort: int = 7102):
        """Function to modify variables in the default XviAutController class to target the Sim Dialogs test
        application, on a system, with a squish server running.

        :param serverAddress: Host IP Address of the system you wish to target with a squish server running
        :type serverAddress: str
        :param serverPort: Network Port number the running squish server. Default value is 4322
        :type serverPort: int, optional
        :param attachPort: Network Port number designated as the squish attaching port for the AUT (startwinaut.exe)
        :type attachPort: int, optional
        """
        aut_cls = cls(serverAddress, serverPort)
        aut_cls._aut_name = SIMDIALOGS_APP_NAME
        aut_cls.attach_port = str(attachPort)
        return aut_cls